import{_ as n,o as r,c as t,a3 as u}from"./chunks/framework.z_KJ15Ep.js";const s="/bilder/schueler/schulbesuch-grundschuldaten.png",g=JSON.parse('{"title":"Daten zum Grundschulbesuch erfassen","description":"","frontmatter":{"title":"Daten zum Grundschulbesuch erfassen","source_pageid":382,"source_revision":3182},"headers":[],"relativePath":"schild3/schueler/grundschuldaten-eingeben-schueler-schulbesuch.md","filePath":"schild3/schueler/grundschuldaten-eingeben-schueler-schulbesuch.md"}'),h={name:"schild3/schueler/grundschuldaten-eingeben-schueler-schulbesuch.md"};function c(i,e,a,l,d,o){return r(),t("div",null,[...e[0]||(e[0]=[u('<h1 id="daten-zum-grundschulbesuch-erfassen" tabindex="-1">Daten zum Grundschulbesuch erfassen <a class="header-anchor" href="#daten-zum-grundschulbesuch-erfassen" aria-label="Permalink to &quot;Daten zum Grundschulbesuch erfassen&quot;">​</a></h1><p>Erfassen Sie Noten, Durchschnitte und weitere Angaben zur zuvor besuchten Grundschule. Der Bereich wird angezeigt, wenn die zuletzt besuchte Schule als Grundschule eingetragen ist.</p><p><a href="/bilder/schueler/schulbesuch-grundschuldaten.png"><img src="'+s+'" alt="Eingabemaske &quot;Grundschuldaten für Nachname, Vorname bearbeiten&quot;." loading="lazy"></a></p><p><em>Eingabemaske &quot;Grundschuldaten für Nachname, Vorname bearbeiten&quot;.</em></p><p>Diese Maske wird aufgerufen durch die Schaltfläche &quot;Grundschuldaten eingeben&quot; auf dem Reiter <em>Schulbesuch</em> im Bereich <em>Vor der Aufnahme besuchte Schule /Einrichtung</em>, wenn es sich dabei um die Schulform &quot;Grundschule&quot; handelt.</p><p>Die Grundschuldaten sind gegliedert in die Bereiche <em>Einzelnoten</em>, <em>Durchschnittsnoten</em> und <em>Sonstige Grundschuldaten</em>.</p><ul><li>Bei den &quot;<strong>Einzelnoten</strong>&quot; können für <em>Deutsch</em> die Einzelnoten zm <em>Sprachgebrauch</em>, <em>Lesen</em> und <em>Rechtschreiben</em>, sowie zu den Fächern <em>Sachunterricht</em>, <em>Mathematik</em>, <em>Englisch</em>, <em>Kunst/Textil</em>, <em>Musik</em>, <em>Sport</em>, und <em>Religion</em> gespeichert werden.</li><li>Die &quot;<strong>Durchschnittsnoten</strong>&quot; können mit der Schaltfläche &quot;<strong>Durchschnitte berechnen</strong>&quot; aus den Einzelnoten berechnet werden. Dabei werden der <em>Durchschnitt Sprache</em> aus den drei Einzelnoten zum Fach Deutsch, der Durchschnitt aller Fächer bei gleicher Gewichtung und der Durchschnitt aller Fächer ohen Religion, bei doppelter Gewichtung der Hauptfächer berechnet.</li><li>Unter &quot;<strong>Sonstige Grundschulangaben</strong>&quot; können der Name der Klassenleitung, die zuletzt besuchte Klasse, die Angabe, ob es sich um Geschwisterkind handelt und Bemerkungen hinterlegt werden.</li></ul><p>Mit der Schaltfläche &quot;<strong>OK</strong>&quot; werden die eingegebenen Daten übernommen, mit der Schaltfläche &quot;<strong>Abbrechen</strong>&quot; wird die Eingabe ohne Übernahme der Daten beendet.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Grundschuldaten_eingeben_(Sch%C3%BCler_Schulbesuch)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 3182.</p>',10)])])}const b=n(h,[["render",c]]);export{g as __pageData,b as default};
